<template>
  <div class="operaciones-page">
    <v-card class="operaciones-header mb-5 rounded-xl" elevation="0" border><v-card-text class="pa-5"><div class="d-flex align-center flex-wrap ga-3"><v-avatar color="primary" variant="tonal" size="48" rounded="lg"><v-icon size="28">mdi-account-cash-outline</v-icon></v-avatar><div><div class="text-h6 font-weight-bold">Deudas de clientes</div><div class="text-body-2 text-medium-emphasis">Saldos originados por ventas a crédito y sus abonos</div></div><v-spacer/><v-chip color="primary" variant="tonal">{{ branch.sucursalActual?.nombre||'Sin sucursal' }}</v-chip></div></v-card-text></v-card>
    <v-alert v-if="error" type="error" variant="tonal" closable class="mb-4" @click:close="error=''">{{ error }}</v-alert>
    <v-row class="mb-3"><v-col cols="12" sm="4"><v-card class="operaciones-metric rounded-xl" border elevation="0"><v-card-text><div class="text-caption text-medium-emphasis">Saldo por cobrar (página)</div><div class="text-h5 font-weight-bold money mt-2">{{ money(pageBalance) }}</div></v-card-text></v-card></v-col><v-col cols="6" sm="4"><v-card class="operaciones-metric rounded-xl" border elevation="0"><v-card-text><div class="text-caption text-medium-emphasis">Pendientes</div><div class="text-h5 font-weight-bold mt-2">{{ items.filter(x=>x.estado==='PENDIENTE'||x.estado==='PARCIAL').length }}</div></v-card-text></v-card></v-col><v-col cols="6" sm="4"><v-card class="operaciones-metric rounded-xl" border elevation="0"><v-card-text><div class="text-caption text-medium-emphasis">Vencidas</div><div class="text-h5 font-weight-bold text-error mt-2">{{ items.filter(x=>x.estado==='VENCIDA').length }}</div></v-card-text></v-card></v-col></v-row>
    <v-card rounded="xl" elevation="0" border class="overflow-hidden"><div class="pa-4 operaciones-toolbar"><v-text-field v-model="search" class="operaciones-search" placeholder="Buscar cliente o documento..." prepend-inner-icon="mdi-magnify" variant="outlined" density="comfortable" rounded="lg" hide-details clearable @keyup.enter="searchNow"/><v-select v-model="status" :items="statuses" class="operaciones-filter" label="Estado" variant="outlined" density="comfortable" rounded="lg" hide-details/><v-btn color="primary" variant="tonal" prepend-icon="mdi-filter" @click="searchNow">Filtrar</v-btn><v-btn icon="mdi-refresh" color="primary" variant="tonal" :loading="loading" @click="load"/></div><v-divider/><div v-if="loading" class="text-center py-14"><v-progress-circular indeterminate color="primary"/></div><template v-else-if="items.length"><v-table hover class="operaciones-table operaciones-desktop"><thead><tr><th>Deuda</th><th>Cliente</th><th>Venta</th><th>Vencimiento</th><th>Estado</th><th class="text-end">Original</th><th class="text-end">Saldo</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.idDeudaCliente"><td>#{{ item.idDeudaCliente }}</td><td><strong>{{ item.cliente.nombre }}</strong><div class="text-caption">{{ item.cliente.numeroDocumento }}</div></td><td>#{{ item.ingresoOrigen.idIngreso }}</td><td>{{ date(item.fechaVencimiento) }}</td><td><v-chip size="small" :color="statusColor(item.estado)" variant="tonal">{{ statusLabel(item.estado) }}</v-chip></td><td class="text-end">{{ money(item.montoOriginal) }}</td><td class="text-end font-weight-bold">{{ money(item.saldoPendiente) }}</td><td><v-btn icon="mdi-eye-outline" variant="text" color="primary" @click="showDetail(item)"/><v-btn v-if="canManage&&openBox&&Number(item.saldoPendiente)>0" icon="mdi-cash-plus" variant="text" color="success" @click="openPayment(item)"/></td></tr></tbody></v-table><div class="operaciones-mobile pa-3"><v-card v-for="item in items" :key="item.idDeudaCliente" variant="outlined" rounded="lg" class="mb-3"><v-card-text><div class="d-flex"><strong>{{ item.cliente.nombre }}</strong><v-spacer/><strong>{{ money(item.saldoPendiente) }}</strong></div><div class="text-caption text-medium-emphasis mt-1">Deuda #{{ item.idDeudaCliente }} · vence {{ date(item.fechaVencimiento) }}</div><div class="d-flex mt-3"><v-chip size="x-small" :color="statusColor(item.estado)">{{ statusLabel(item.estado) }}</v-chip><v-spacer/><v-btn size="small" variant="text" @click="showDetail(item)">Detalle</v-btn><v-btn v-if="canManage&&openBox&&Number(item.saldoPendiente)>0" size="small" color="success" variant="text" @click="openPayment(item)">Abonar</v-btn></div></v-card-text></v-card></div></template><div v-else class="operaciones-empty"><v-icon size="50">mdi-account-cash-outline</v-icon><div class="mt-2">No se encontraron deudas</div></div><v-divider/><div class="d-flex justify-space-between align-center pa-3"><span class="text-caption">Mostrando {{ items.length }} de {{ total }}</span><v-pagination v-if="total>limit" v-model="page" :length="Math.ceil(total/limit)" size="small"/></div></v-card>
    <v-dialog v-model="paymentDialog" max-width="650" persistent><v-card rounded="xl"><v-card-title class="operaciones-dialog-title"><span class="operaciones-dialog-icon"><v-icon>mdi-cash-plus</v-icon></span>Registrar abono<v-spacer/><v-btn icon="mdi-close" variant="text" color="on-primary" @click="paymentDialog=false"/></v-card-title><v-card-text class="pa-5"><v-alert v-if="formError" type="error" variant="tonal" class="mb-4">{{ formError }}</v-alert><div class="mb-4"><strong>{{ actionDebt?.cliente.nombre }}</strong><div class="text-body-2 text-medium-emphasis">Saldo pendiente: {{ money(actionDebt?.saldoPendiente||0) }}</div></div><label class="operaciones-field-label">Monto del abono *</label><v-text-field v-model="amount" prefix="S/" type="number" min="0.01" step="0.01" variant="outlined" @update:model-value="syncSinglePayment"/><PagosEditor v-model="payments" :medios="paymentMethods"/><label class="operaciones-field-label mt-4">Detalle</label><v-text-field v-model="detail" variant="outlined" maxlength="500"/></v-card-text><v-card-actions class="pa-4"><v-spacer/><v-btn variant="text" @click="paymentDialog=false">Cancelar</v-btn><v-btn color="success" :loading="saving" @click="savePayment">Registrar abono</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog :model-value="!!selected" max-width="720" @update:model-value="selected=null"><v-card v-if="selected" rounded="xl"><v-card-title class="pa-5 d-flex">Deuda #{{ selected.idDeudaCliente }}<v-spacer/><v-chip :color="statusColor(selected.estado)">{{ statusLabel(selected.estado) }}</v-chip></v-card-title><v-card-text class="px-5 pb-5"><div class="text-h6">{{ selected.cliente.nombre }}</div><div class="text-caption text-medium-emphasis">{{ selected.cliente.tipoDocumento.nombre }} {{ selected.cliente.numeroDocumento }}</div><v-row class="mt-4"><v-col cols="4"><div class="text-caption">Original</div><strong>{{ money(selected.montoOriginal) }}</strong></v-col><v-col cols="4"><div class="text-caption">Abonado</div><strong>{{ money(selected.montoAbonado) }}</strong></v-col><v-col cols="4"><div class="text-caption">Saldo</div><strong>{{ money(selected.saldoPendiente) }}</strong></v-col></v-row><v-divider class="my-4"/><div class="font-weight-bold mb-2">Historial de abonos</div><v-list v-if="selected.abonos.length"><v-list-item v-for="a in selected.abonos" :key="a.idAbonoDeudaCliente" :title="money(a.ingresoAbono.monto)" :subtitle="`${dateTime(a.ingresoAbono.fechaIngreso)} · ${a.ingresoAbono.detalle||'Abono'}`"/></v-list><div v-else class="text-medium-emphasis">Aún no tiene abonos.</div></v-card-text><v-card-actions><v-spacer/><v-btn variant="text" color="primary" @click="selected=null">Cerrar</v-btn></v-card-actions></v-card></v-dialog><v-snackbar v-model="notice" color="success">Abono registrado correctamente</v-snackbar>
  </div>
</template>
<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { getApiErrorMessage } from '@/core/api/api-error'
import { mediosPagoApi } from '@/core/api/administracion.api'
import { Permiso } from '@/core/constants/permisos'
import type { MedioPago } from '@/core/types/administracion.types'
import { useAuthStore } from '@/modules/auth/auth.store'
import { useSucursalStore } from '@/shared/stores/sucursal.store'
import PagosEditor from '../components/PagosEditor.vue'
import { cajasApi, deudasApi } from '../operaciones.api'
import type { Caja, DeudaCliente, PagoPayload } from '../operaciones.types'
import '../operaciones.css'
type Status=DeudaCliente['estado']
const auth=useAuthStore(),branch=useSucursalStore(),canManage=computed(()=>auth.puede(Permiso.DEUDAS_GESTIONAR)),items=ref<DeudaCliente[]>([]),selected=ref<DeudaCliente|null>(null),actionDebt=ref<DeudaCliente|null>(null),openBox=ref<Caja|null>(null),paymentMethods=ref<MedioPago[]>([]),payments=ref<PagoPayload[]>([]),search=ref(''),status=ref<Status|null>(null),statuses=[{title:'Todos',value:null},{title:'Pendiente',value:'PENDIENTE'},{title:'Parcial',value:'PARCIAL'},{title:'Pagada',value:'PAGADA'},{title:'Vencida',value:'VENCIDA'}],page=ref(1),limit=30,total=ref(0),loading=ref(false),saving=ref(false),paymentDialog=ref(false),error=ref(''),formError=ref(''),notice=ref(false),amount=ref(''),detail=ref('')
const pageBalance=computed(()=>items.value.reduce((s,x)=>s+Number(x.saldoPendiente),0))
async function load(){if(!branch.idSucursalActual){items.value=[];return}loading.value=true;error.value='';try{const r=await deudasApi.listar({idSucursal:branch.idSucursalActual,pagina:page.value,limite:limit,buscar:search.value.trim()||undefined,estado:status.value??undefined});items.value=r.data.data;total.value=r.data.total;try{openBox.value=(await cajasApi.abierta(branch.idSucursalActual)).data}catch{openBox.value=null}}catch(cause){error.value=getApiErrorMessage(cause,'No se pudieron cargar las deudas')}finally{loading.value=false}}
async function showDetail(item:DeudaCliente){try{selected.value=(await deudasApi.obtener(item.idDeudaCliente)).data}catch(cause){error.value=getApiErrorMessage(cause)}}async function openPayment(item:DeudaCliente){actionDebt.value=item;amount.value='';detail.value='';payments.value=[];formError.value='';paymentDialog.value=true;try{paymentMethods.value=(await mediosPagoApi.listar()).data}catch(cause){formError.value=getApiErrorMessage(cause)}}function syncSinglePayment(){if(payments.value.length===1)payments.value=[{...payments.value[0]!,monto:amount.value}]}
async function savePayment(){if(!actionDebt.value||!openBox.value||!branch.idSucursalActual)return;const value=Number(amount.value),distributed=payments.value.reduce((s,x)=>s+Number(x.monto||0),0);if(!(value>0)||value>Number(actionDebt.value.saldoPendiente)+.001){formError.value='Ingresa un monto válido que no supere el saldo';return}if(Math.abs(value-distributed)>.001){formError.value='La distribución debe coincidir con el monto del abono';return}saving.value=true;try{await deudasApi.abonar(actionDebt.value.idDeudaCliente,{idCaja:openBox.value.idCaja,idSucursal:branch.idSucursalActual,monto:value.toFixed(2),detalle:detail.value.trim()||undefined,pagos:payments.value});paymentDialog.value=false;notice.value=true;await load()}catch(cause){formError.value=getApiErrorMessage(cause)}finally{saving.value=false}}
function searchNow(){if(page.value!==1)page.value=1;else void load()}function statusLabel(v:Status){return({PENDIENTE:'Pendiente',PARCIAL:'Parcial',PAGADA:'Pagada',VENCIDA:'Vencida'}as const)[v]}function statusColor(v:Status){return({PENDIENTE:'warning',PARCIAL:'info',PAGADA:'success',VENCIDA:'error'}as const)[v]}function money(v:string|number){return new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(Number(v)||0)}function date(v:string|null){return v?new Intl.DateTimeFormat('es-PE',{dateStyle:'medium'}).format(new Date(`${v.slice(0,10)}T12:00:00`)):'Sin fecha'}function dateTime(v:string){return new Intl.DateTimeFormat('es-PE',{dateStyle:'short',timeStyle:'short'}).format(new Date(v))}
watch([()=>branch.idSucursalActual,page],()=>void load(),{immediate:true})
</script>
